package vn.edu.fpt.seal.modules.support.entity; import jakarta.persistence.*; import lombok.*; import vn.edu.fpt.seal.common.entity.BaseEntity; import vn.edu.fpt.seal.modules.user.entity.User; @Entity @Table(name="support_tickets") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class SupportTicket extends BaseEntity{ @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="requester_id") private User requester; @Column(nullable=false,length=50) private String category; @Column(nullable=false,length=20) private String priority; @Column(nullable=false,length=255) private String subject; @Column(nullable=false,columnDefinition="text") private String description; @Column(nullable=false,length=30) @Builder.Default private String status="open"; }
